    snapshot_id, tenant_id, product_id, approval_mode, product_profile_ref,
    project_trust_ref, rules_schema_version, rules_payload, rules_hash,
    content_digest, created_at
) VALUES (
    #{row.snapshotId}, #{row.tenantId}, #{row.productId}, #{row.approvalMode},
    #{row.productProfileRef}, #{row.projectTrustRef}, #{row.rulesSchemaVersion},
    #{row.rulesPayload}, #{row.rulesHash}, #{row.contentDigest}, #{row.createdAt}
)

INSERT INTO approval_response_metadata (
    response_id, responder_tenant_id, responder_principal_id, responder_principal_type,
    authority_outcome, authority_reason_code, target_outcome, target_reason_code,
    selected_reuse_scope, validation_digest
) VALUES (
    #{responseId}, #{responderTenantId}, #{responderPrincipalId}, #{responderPrincipalType},
    #{authorityOutcome}, #{authorityReasonCode}, #{targetOutcome}, #{targetReasonCode},
    #{selectedReuseScope}, #{validationDigest}
)

INSERT INTO policy_authorization_evidence (
    decision_id, request_digest, requester_tenant_id, requester_principal_id,
    requester_principal_type, responder_tenant_id, responder_principal_id,
    responder_principal_type, approved_at, expires_at
) VALUES (
    #{row.decisionId}, #{row.requestDigest}, #{row.requesterTenantId},
    #{row.requesterPrincipalId}, #{row.requesterPrincipalType},
    #{row.responderTenantId}, #{row.responderPrincipalId},
    #{row.responderPrincipalType}, #{row.approvedAt}, #{row.expiresAt}
)

mapper.select:
SELECT  FROM approval_grant
WHERE tenant_id = #{tenantId}
  AND requester_principal_id = #{principalId}
  AND requester_principal_type = #{principalType}
  AND product_id = #{productId}
  AND capability = #{capability}
  AND operation = #{operation}
  AND target_type = #{targetType}
ORDER BY grant_id
